using System.Diagnostics;
using System.Text.Json;
using AgvDispatch.Application.Abstractions;
using AgvDispatch.Application.Traffic;
using AgvDispatch.Domain.Maps;

var checks=0;void Check(bool good,string name){if(!good)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
var nodes=new[]{new MapNode("A",0,0,MapNodeType.Waypoint,true,[]),new("B",2,0,MapNodeType.Waypoint,true,[]),new("C",1,-2,MapNodeType.Waypoint,true,[]),new("D",1,2,MapNodeType.Waypoint,true,[])};
var edges=new[]{new MapEdge("AB","A","B",2,1,true,true,[]),new("CD","C","D",4,1,true,true,[])};
var map=new MapDefinition("test","","LocalCartesian","m",nodes,edges,[]);
TrafficGeometryRoute Route(string vehicle,string[] path,string[] ids)=>new("T-"+vehicle,"S-"+vehicle,vehicle,"M","V","LocalCartesian",path,ids,new("PROFILE",vehicle,"LocalCartesian",.5,true,true),0);
var a=Route("AGV-A",["A","B"],["AB"]);var b=Route("AGV-B",["C","D"],["CD"]);var policy=new TrafficGeometryPreviewPolicy{Enabled=true,UseSpatialIndex=false};
TrafficGeometryPreview Eval(MapDefinition? m=null,TrafficGeometryRoute? x=null,TrafficGeometryRoute? y=null,TrafficGeometryPreviewPolicy? p=null)=>TrafficGeometryPreviewEvaluator.Evaluate(m??map,"M","V",x??a,y??b,p??policy);
var cross=Eval();Check(cross.Available&&cross.Complete&&cross.Conflicts.Single().Kind==TrafficGeometryConflictKind.LineEnvelopeOverlap,"两条直线路径交叉识别圆车体包络交叠");
Check(!cross.ResourcesLocked&&!cross.ResourcesReleased,"纯预检无加锁释放或通信");
void Refuse(string name,MapDefinition? m=null,TrafficGeometryRoute? x=null,TrafficGeometryRoute? y=null,TrafficGeometryPreviewPolicy? p=null){var result=Eval(m,x,y,p);Check(!result.Available&&!result.CanConcludeSeparated,name);}
Refuse("默认关闭",p:new());Refuse("地图单位非米",m:map with{Unit="mm"});Refuse("路线旧地图版本",x:a with{MapVersionId="OLD"});Refuse("路线坐标系不符",x:a with{CoordinateFrameId="OTHER"});
Refuse("缺车体标定",x:a with{Body=null});Refuse("标定未确认",x:a with{Body=a.Body! with{CalibrationVerified=false}});Refuse("最大载荷未覆盖",x:a with{Body=a.Body! with{IncludesMaximumPermittedLoad=false}});
Refuse("包络属于其他车",x:a with{Body=a.Body! with{VehicleId="OTHER"}});Refuse("包络坐标系不符",x:a with{Body=a.Body! with{CoordinateFrameId="OTHER"}});Refuse("无限半径",x:a with{Body=a.Body! with{RadiusFromReportedReferenceMeters=double.PositiveInfinity}});
Refuse("误差界缺失",x:a with{PositionUncertaintyMeters=double.NaN});Refuse("误差界过大",x:a with{PositionUncertaintyMeters=.5});Refuse("负误差界",x:a with{PositionUncertaintyMeters=-1});
Refuse("未知节点",x:a with{NodeIds=["A","UNKNOWN"]});Refuse("普通绘图线不是导航路段",x:a with{EdgeIds=["CAD-LINE"]});Refuse("不完整路径",x:a with{NodeIds=["A"]});Refuse("空路径",x:a with{NodeIds=[],EdgeIds=[]});
Refuse("禁用路段",m:map with{Edges=[edges[0] with{Enabled=false},edges[1]]});Refuse("重复节点编号",m:map with{Nodes=[..nodes,nodes[0] with{Id="a"}]});Refuse("非有限坐标",m:map with{Nodes=[nodes[0] with{X=double.NaN},nodes[1],nodes[2],nodes[3]]});
Refuse("单向路线反向",m:map with{Edges=[edges[0] with{Bidirectional=false},edges[1]]},x:a with{NodeIds=["B","A"]});
Check(Eval(x:a with{NodeIds=["B","A"]}).Available,"双向路线反向仍可预检");
Refuse("同车重复路线",y:b with{VehicleId="AGV-A",Body=b.Body! with{VehicleId="AGV-A"}});
Refuse("无安全裕量",p:new(){Enabled=true,SafetyMarginMeters=0});Refuse("无比较预算",p:new(){Enabled=true,MaximumComparisons=0});
MapDefinition Parallel(double y)=>map with{Nodes=[nodes[0],nodes[1],nodes[2] with{X=0,Y=y},nodes[3] with{X=2,Y=y}]};
Check(Eval(Parallel(1.3)).Conflicts.Count==1,"两车包络加裕量刚好接触算交叠");
Check(Eval(Parallel(1.31)).CanConcludeSeparated,"超过完整包络间隙可在本空间模型判定分离");
Check(!Eval(Parallel(1.5),x:a with{PositionUncertaintyMeters=.25},y:b with{PositionUncertaintyMeters=.25}).CanConcludeSeparated,"定位误差扩大扫掠包络");
var diagonal=map with{Nodes=[nodes[0],nodes[1] with{X=10,Y=10},nodes[2] with{X=0,Y=2},nodes[3] with{X=10,Y=12}]};
Check(Eval(diagonal).CanConcludeSeparated,"直线包围盒重叠但胶囊实际分离不多报");
var bezier=map with{Edges=[edges[0] with{GeometryKind=MapEdgeGeometryKind.CubicBezier,ControlPoints=[new(0,3),new(2,3)]},edges[1]]};
var curve=Eval(bezier);Check(curve.Available&&curve.Conflicts.Single().Kind==TrafficGeometryConflictKind.ConservativeCurveOverlap,"Bezier采用保守包围范围标记待核对");
var box=MapEdgeGeometry.ConservativeBounds(bezier.Edges[0],nodes[0],nodes[1]);
Check(MapEdgeGeometry.Sample(bezier.Edges[0],nodes[0],nodes[1],1000).All(p=>p.X>=box.MinX&&p.X<=box.MaxX&&p.Y>=box.MinY&&p.Y<=box.MaxY),"Bezier解析控制包围范围覆盖密集独立采样");
var arc=map with{Edges=[edges[0] with{GeometryKind=MapEdgeGeometryKind.CircularArc,ControlPoints=[new(1,1)]},edges[1]]};
box=MapEdgeGeometry.ConservativeBounds(arc.Edges[0],nodes[0],nodes[1]);
Check(Math.Abs(box.MinY)<1e-9&&Math.Abs(box.MaxY-1)<1e-9&&MapEdgeGeometry.Sample(arc.Edges[0],nodes[0],nodes[1],1000).All(p=>p.X>=box.MinX-1e-12&&p.X<=box.MaxX+1e-12&&p.Y>=box.MinY-1e-12&&p.Y<=box.MaxY+1e-12),"圆弧包围范围只含实际扫过的极值且覆盖密集采样");
Refuse("圆弧控制点共线",m:arc with{Edges=[arc.Edges[0] with{ControlPoints=[new(1,0)]},edges[1]]});
Refuse("Bezier控制点数量错误",m:bezier with{Edges=[bezier.Edges[0] with{ControlPoints=[]},edges[1]]});
Check(!Eval(arc with{Nodes=[nodes[0],nodes[1],nodes[2] with{X=0,Y=-1.2},nodes[3] with{X=2,Y=-1.2}]}).CanConcludeSeparated,"圆弧实际扫过范围贴近对向路线时不能误判安全");
Check(Eval(arc with{Nodes=[nodes[0],nodes[1],nodes[2] with{X=0,Y=-1.5},nodes[3] with{X=2,Y=-1.5}]}).Available,"圆弧未扫过的半圆不再按整圆多报");
Refuse("空节点编号",x:a with{NodeIds=["A",null!]});
Refuse("过大坐标",m:map with{Nodes=[nodes[0] with{X=1e7},nodes[1],nodes[2],nodes[3]]});
Check(!TrafficGeometryPreviewEvaluator.Evaluate(map,"M","V",a,b,null!).Available,"缺预检配置不可用");
var bn=Enumerable.Range(0,101).Select(i=>new MapNode("N"+i,i,0,MapNodeType.Waypoint,true,[])).ToArray();
var en=Enumerable.Range(0,100).Select(i=>new MapEdge("E"+i,"N"+i,"N"+(i+1),1,1,true,true,[])).ToArray();
var large=new MapDefinition("large","","LocalCartesian","m",bn,en,[]);var path=bn.Select(n=>n.Id).ToArray();var ids=en.Select(e=>e.Id).ToArray();
var largeA=Route("AGV-A",path,ids);var largeB=Route("AGV-B",path,ids);
var budget=Eval(large,largeA,largeB,new(){Enabled=true,UseSpatialIndex=false,MaximumComparisons=50,MaximumReportedConflicts=1000});
Check(budget.Available&&!budget.Complete&&budget.Comparisons==50&&!budget.CanConcludeSeparated,"预算耗尽明确不完整不能判定无冲突");
var limited=Eval(large,largeA,largeB,new(){Enabled=true,MaximumReportedConflicts=1});
Check(!limited.Complete&&limited.Conflicts.Count==1,"冲突报告数量上限不伪装完整评估");
Refuse("路径边数量超限",m:large,x:largeA,y:largeB,p:new(){Enabled=true,MaximumEdgesPerRoute=10});
using(var cancel=new CancellationTokenSource()){cancel.Cancel();var stopped=false;try{TrafficGeometryPreviewEvaluator.Evaluate(map,"M","V",a,b,policy,cancel.Token);}catch(OperationCanceledException){stopped=true;}Check(stopped,"主动取消传播");}
var timer=Stopwatch.StartNew();var complete=Eval(large,largeA,largeB,new(){Enabled=true,UseSpatialIndex=false,MaximumReportedConflicts=1000});timer.Stop();
Check(complete.Complete&&complete.Comparisons==10000,"百段双路线完整一万次比较");
File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"geometry-result.json"),JsonSerializer.Serialize(new{Checks=checks,LargeRouteMilliseconds=timer.Elapsed.TotalMilliseconds,Scope="pure read-only spatial envelope preview; no scheduling, devices or resource writes",Cross=cross,Curve=curve},new JsonSerializerOptions{WriteIndented=true}));
Console.WriteLine($"PASS {checks} geometry preview checks; 10000 comparisons: {timer.Elapsed.TotalMilliseconds:F2} ms.");
